sap.ui.define([
  "sap/ui/core/mvc/Controller",
  "sap/ui/core/Messaging",
  "sap/ui/core/message/Message",
  "sap/ui/core/message/MessageType"
], function (Controller, Messaging, Message, MessageType) {
  "use strict";

  return Controller.extend("my.app.controller.Edit", {
    onInit: function () {
      const view = this.getView();
      view.setModel(Messaging.getMessageModel(), "message");
      Messaging.registerObject(view, true); // validation messages for this view's bindings
    },

    _addOwnMessage: function () {
      Messaging.addMessages(new Message({
        message: "Delivery date is in the past",
        type: MessageType.Warning,
        target: "/deliveryDate",
        processor: this.getView().getModel()
      }));
    }
  });
});

sap.ui.require([
  "sap/ui/core/Messaging",
  "sap/ui/core/message/Message",
  "sap/ui/core/message/MessageType"
], function (Messaging, Message, MessageType) {
  Messaging.addMessages(new Message({
    message: this.getText("priceTooHigh"),
    type: MessageType.Error,
    target: "/Products('HT-1000')/Price",
    processor: this.getView().getModel()   // the Price field turns red
  }));

  // later
  Messaging.removeAllMessages();
}.bind(this));

private messagePopover?: MessagePopover;

public async onMessagePopoverPress(event: Button$PressEvent): Promise<void> {
  if (!this.messagePopover) {
    this.messagePopover = await Fragment.load({
      id: this.getView().getId(),
      name: "my.app.view.fragment.MessagePopover",
      controller: this
    }) as MessagePopover;
    this.getView().addDependent(this.messagePopover);
  }
  this.messagePopover.openBy(event.getSource());
}

// MessageItem: activeTitle="{= !!${message>target} }"
public onActiveTitlePress(event: MessagePopover$ActiveTitlePressEvent): void {
  const message = event.getParameter("item").getBindingContext("message").getObject() as Message;
  const control = Element.getElementById(message.getControlId());
  control?.focus();   // jump to the field the message refers to
}

