// Detail controller: notify after saving
onSave: function () {
  // ... save ...
  this.getOwnerComponent().getEventBus().publish("orders", "saved", { orderId: "4711" });
},

// List controller: listen and clean up
onInit: function () {
  this.getOwnerComponent().getEventBus().subscribe("orders", "saved", this._onOrderSaved, this);
},

onExit: function () {
  this.getOwnerComponent().getEventBus().unsubscribe("orders", "saved", this._onOrderSaved, this);
},

_onOrderSaved: function (channel, event, data) {
  this.byId("ordersTable").getBinding("items").refresh();
}
